action.code:
RouteModel::Node* lowest_f_node = open_list[0];
float lowest_f = lowest_f_node->g_value + lowest_f_node->h_value;
size_t lowest_index = 0;

for (size_t i = 1; i < open_list.size(); i++) {
    float current_f = open_list[i]->g_value + open_list[i]->h_value;
    if (current_f < lowest_f) {
        lowest_f = current_f;
        lowest_f_node = open_list[i];
        lowest_index = i;
    }
}

open_list.erase(open_list.begin() + lowest_index);
return lowest_f_node;

